-- Compass OOU: the 84 places we have so far. Run AFTER schema.sql. Safe to run again (it updates by name).
on conflict (name) do update set slug=excluded.slug,category=excluded.category,type_label=excluded.type_label,faculty=excluded.faculty,aliases=excluded.aliases,note=excluded.note,lat=excluded.lat,lng=excluded.lng,location_source=excluded.location_source,verified=excluded.verified,sort_order=excluded.sort_order;
